package main

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

func TestProbeBodyCap(t *testing.T) {
	store := NewStore(time.Minute)
	handler := sessionHandler(store)

	// Normal small body: fine.
	rec := httptest.NewRecorder()
	req := httptest.NewRequest("POST", "/session?id=s1&user=u", strings.NewReader(strings.Repeat("x", 100)))
	handler(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("small body status = %d, want 200", rec.Code)
	}

	// Body over 1 MiB: 413.
	huge := strings.Repeat("x", (1<<20)+1024)
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/session?id=s2&user=u", strings.NewReader(huge))
	handler(rec, req)
	if rec.Code != http.StatusRequestEntityTooLarge {
		t.Fatalf("huge body status = %d, want 413", rec.Code)
	}

	// Exactly at the cap: allowed (cap is inclusive).
	atCap := strings.Repeat("x", 1<<20)
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/session?id=s3&user=u", strings.NewReader(atCap))
	handler(rec, req)
	if rec.Code == http.StatusRequestEntityTooLarge {
		t.Fatal("body exactly at cap must not be rejected")
	}

	// boundedBody returns a LimitedReader with the right N.
	req = httptest.NewRequest("POST", "/session?id=s4&user=u", strings.NewReader("abc"))
	lr := boundedBody(req)
	if lr.N != int64(maxRequestBodyBytes) {
		t.Fatalf("boundedBody N = %d, want %d", lr.N, maxRequestBodyBytes)
	}
}
EOF
